const $=s=>document.querySelector(s), esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'LKR '+n.toLocaleString('en-LK'), compact=n=>'LKR '+(n/1000000).toFixed(2)+'M';
let storageOK=true;function load(k,f){try{return JSON.parse(localStorage.getItem(k))||f}catch{storageOK=false;return f}}function persist(){try{localStorage.setItem('vx-rules',JSON.stringify(rules));localStorage.setItem('vx-cases',JSON.stringify(cases))}catch{storageOK=false;toast('Storage unavailable. Changes last for this session.')}}
let mode=load('vx-mode','rules'), modelConfig=load('vx-models',{z:3,iqr:1.5,method:'zscore',threshold:.62,trees:64});
let rules=load('vx-rules',structuredClone(GL.defaults)),cases=load('vx-cases',{}),rows=GL.generate(),alerts=GL.evaluate(rows,rules),page='overview',query='',branch='All branches',severity='All severities',status='All statuses';
let governance=load('vx-governance-v1',null)||Governance.init(rules),identity=load('vx-identity','author-a');
rules=governance.rules;
const currentUser=()=>Governance.users.find(u=>u.id===identity)||Governance.users[0];
function saveGovernance(){rules=governance.rules;try{localStorage.setItem('vx-governance-v1',JSON.stringify(governance));localStorage.setItem('vx-identity',JSON.stringify(identity))}catch{toast('Governance changes last for this session only.')}persist();alerts=detect();}
function detect(){return mode==='statistical'?Analytics.statistical(rows,modelConfig).filter(t=>t.flagged):mode==='machine'?Analytics.machine(rows,modelConfig).filter(t=>t.flagged):GL.evaluate(rows,rules)}
alerts=detect();
const modeName=()=>({rules:'Rule-based',statistical:'Statistical',machine:'Machine learning'}[mode]);
const recon=[{id:'REC-001',account:'Cash at bank',branch:'Colombo',gl:12450000,source:12425000,reason:'Bank fee not posted',age:3},{id:'REC-002',account:'Interbranch clearing',branch:'Galle',gl:1800000,source:1650000,reason:'Counterpart posting missing',age:7},{id:'REC-003',account:'Customer deposits',branch:'Kandy',gl:8600000,source:8680000,reason:'Settlement timing difference',age:1},{id:'REC-004',account:'Interest receivable',branch:'Kurunegala',gl:3250000,source:3250000,reason:'Matched',age:0}];
let investigations=load('vx-investigations-v2',null)||migrateInvestigations(cases);
const state=id=>{let c=Investigations.find(investigations,id);return c?{...c,owner:c.owner||'Unassigned'}:{status:'New',owner:'Unassigned',notes:[]}}, badge=(s)=>`<span class="pill ${s}">${s}</span>`;
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500)}
function heading(title,sub,buttons=''){return `<div class="heading"><div><div class="eyebrow">GL RISK INTELLIGENCE</div><h1>${title}</h1><p>${sub}</p></div><div class="actions">${buttons}</div></div>`}
function filtered(data){return data.filter(t=>(branch==='All branches'||t.branch===branch)&&(severity==='All severities'||t.severity===severity)&&(status==='All statuses'||state(t.id).status===status)&&(!query||[t.id,t.account,t.reference,t.description,t.branch,t.type,t.sourceSystem].join(' ').toLowerCase().includes(query.toLowerCase())))}
function filters(isAlerts=true){return `<div class="filters"><input type="search" id="search" aria-label="Search journals" placeholder="Search journal, account or reference…" value="${esc(query)}"><select id="branch" aria-label="Branch">${['All branches',...GL.branches].map(x=>`<option ${x===branch?'selected':''}>${x}</option>`).join('')}</select>${isAlerts?`<select id="severity" aria-label="Severity">${['All severities','High','Medium'].map(x=>`<option ${x===severity?'selected':''}>${x}</option>`).join('')}</select><select id="status" aria-label="Case status">${['All statuses',...Investigations.statuses].map(x=>`<option ${x===status?'selected':''}>${x}</option>`).join('')}</select>`:''}<button id="clear">Clear filters</button></div>`}
function table(data,isAlerts=true){return `<div class="tablewrap"><table><thead><tr><th>Journal / account</th><th>Branch / date</th>${isAlerts?'<th>Detection signal</th><th>Severity</th>':'<th>Reference</th><th>Side</th>'}<th class="right">Amount</th>${isAlerts?'<th>Status</th>':''}<th></th></tr></thead><tbody>${data.map(t=>`<tr class="clickable" data-detail="${t.id}"><td><strong>${t.id}</strong><small>${esc(t.account)}</small><small>${esc(t.type||'')} · ${esc(t.sourceSystem||'')}</small></td><td>${t.branch}<small>${t.date} · ${String(t.hour).padStart(2,'0')}:00</small></td>${isAlerts?`<td>${esc(t.hits[0].name)}${t.hits.length>1?` <span class="pill">+${t.hits.length-1}</span>`:''}</td><td>${badge(t.severity)}</td>`:`<td>${t.reference}</td><td>${t.side}</td>`}<td class="right"><strong>${money(t.amount)}</strong></td>${isAlerts?`<td>${badge(state(t.id).status)}${investigations.feedback[t.id]?'<small>'+esc(investigations.feedback[t.id].status)+'</small>':''}</td>`:''}<td><button class="link" data-detail="${t.id}" aria-label="Investigate ${t.id}">View ↗</button></td></tr>`).join('')||'<tr><td colspan="7" class="empty">No journals match these filters.</td></tr>'}</tbody></table></div>`}
function render(){page=location.hash.slice(1)||'overview';if(!['overview','exceptions','transactions','rules','reconciliation','models','governance','investigations'].includes(page))page='overview';document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.dataset.page===page));let html='';
if(page==='overview'){const high=alerts.filter(x=>x.severity==='High').length,total=rows.reduce((s,t)=>s+t.amount,0),risk=alerts.reduce((s,t)=>s+t.amount,0);html=heading('A clearer view of ledger risk','Monitor unusual activity. Understand the signals. Act with confidence.','<span class="pill">01–30 Sep 2026</span><button id="run" class="primary">↻ Run detection</button>')+`<div class="stats"><div class="stat accent"><label>Journals analysed</label><strong>${rows.length}</strong><small>${compact(total)} total journal value</small></div><div class="stat"><label>Flagged journals</label><strong>${alerts.length} <span style="font-size:13px;color:#8796a5">/ ${rows.length}</span></strong><small>${(alerts.length/rows.length*100).toFixed(1)}% of synthetic journals</small></div><div class="stat warn"><label>High-severity exceptions</label><strong>${high}</strong><small>${alerts.filter(x=>!['Resolved','Closed'].includes(state(x.id).status)).length} unresolved flagged journals</small></div><div class="stat"><label>Flagged journal value</label><strong>${compact(risk)}</strong><small>Unique journals · not an estimated loss</small></div></div><div class="grid"><section class="panel"><div class="panelhead"><div><h2>Risk signals over time</h2><small>Flagged journals by posting date · September 2026</small></div><span class="pill">Daily</span></div><div class="chart">${Array.from({length:30},(_,i)=>{let n=alerts.filter(t=>+t.date.slice(-2)===i+1).length;return `<div class="barcol" title="Sep ${i+1}: ${n} flagged journals"><small>${n||''}</small><div class="bar ${n?'hot':''}" style="height:${n?Math.max(15,n*42):3}px"></div></div>`}).join('')}</div><div class="chartlabels"><span>01 Sep</span><span>10 Sep</span><span>20 Sep</span><span>30 Sep</span></div><div class="legend"><i></i> ${modeName()} detection · ${mode==='rules'?rules.filter(r=>r.enabled).length+' active rules':'Historical baseline: August 2026'}</div></section><section class="panel"><div class="panelhead"><div><h2>What’s driving exceptions</h2><small>${modeName()} signals · illustrative results</small></div></div>${(mode==='rules'?rules:[{id:mode==='statistical'?'STAT':'ML',name:modeName()+' signal'}]).map(r=>({r,n:alerts.filter(t=>t.hits.some(h=>h.id===r.id)).length})).sort((a,b)=>b.n-a.n).slice(0,5).map(({r,n})=>`<div class="rulebar"><span>${esc(r.name)}</span><div class="track"><i style="width:${n/Math.max(1,alerts.length)*100}%"></i></div><b>${n}</b></div>`).join('')}</section></div><section class="panel"><div class="panelhead"><div><h2>Priority investigation queue</h2><small>Highest risk scores first · click a journal to inspect evidence</small></div><a class="link" href="#exceptions">View all exceptions →</a></div>${table([...alerts].sort((a,b)=>b.score-a.score).slice(0,5))}</section>`;}
if(page==='exceptions'||page==='transactions'){let is=page==='exceptions',data=filtered(is?alerts:rows);html=heading(is?'Exception workbench':'General ledger',is?'Review detection evidence, assign an investigator and document decisions.':'Explore the synthetic posting population used by the detection engine.','<button id="export">↓ Export CSV</button>')+(is?'':ledgerCoverage())+filters(is)+`<section class="panel"><div class="panelhead"><h2>${is?'Detected exceptions':'Synthetic journal register'}</h2><span class="count">${data.length} journals</span></div>${table(data,is)}</section>`;}
if(page==='rules')html=managedRules();
if(page==='governance')html=governancePage();
if(page==='investigations')html=investigationPage();
if(page==='reconciliation'){let delta=recon.reduce((s,r)=>s+Math.abs(r.gl-r.source),0);html=heading('Reconciliation intelligence','Illustrative GL-to-source balances as at 30 September 2026.','<button id="exportRecon">↓ Export CSV</button>')+`<div class="stats"><div class="stat"><label>Accounts compared</label><strong>4</strong><small>Synthetic balance snapshots</small></div><div class="stat warn"><label>Unmatched accounts</label><strong>3</strong><small>Absolute variance greater than zero</small></div><div class="stat"><label>Total absolute variance</label><strong>${money(delta)}</strong><small>Not netted across accounts</small></div><div class="stat accent"><label>Matched accounts</label><strong>1</strong><small>Zero balance variance</small></div></div><section class="panel"><div class="panelhead"><div><h2>Balance comparison</h2><small>Click an exception for investigation and illustrative supporting evidence</small></div></div><div class="tablewrap"><table><thead><tr><th>Account / branch</th><th>GL balance</th><th>Source balance</th><th>GL − source</th><th>Exception / age</th><th>Status</th><th></th></tr></thead><tbody>${recon.map(r=>`<tr><td><strong>${r.account}</strong><small>${r.branch} · ${r.id}</small></td><td>${money(r.gl)}</td><td>${money(r.source)}</td><td>${money(r.gl-r.source)}</td><td>${r.reason}<small>${r.age} days outstanding</small></td><td>${badge(r.gl===r.source?'Matched':state(r.id).status)}</td><td><button class="link" data-recon="${r.id}">View ↗</button></td></tr>`).join('')}</tbody></table></div></section><div class="callout" style="margin-top:20px">Balances are standalone synthetic snapshots; they are not derived from the journal register. Matching uses exact balance equality for this prototype. Production matching, timing tolerances, ageing and source integrations require agreed business specifications.</div>`;}
if(page==='models')html=studio();
if(['overview','exceptions','transactions'].includes(page))html=modeSelector()+html;
$('#main').innerHTML=html;bind();}
function download(name,data){const csv=data.map(row=>row.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n');let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function exportJournals(){let data=filtered(page==='exceptions'?alerts:rows);download('SYNTHETIC-GL-'+page+'.csv',[['Demo data','Journal','Date','Branch','Account','Reference','Side','LKR amount','Transaction type','Source system','Detection method','Signals','Status','Review feedback'],...data.map(t=>['SYNTHETIC',t.id,t.date,t.branch,t.account,t.reference,t.side,t.amount,t.type,t.sourceSystem,modeName(),t.hits?.map(r=>r.name).join('; ')||'',state(t.id).status,investigations.feedback[t.id]?.status||'Not reviewed'])]);}
function bind(){bindInvestigations();bindGovernance();bindModels();document.querySelectorAll('[data-detail]').forEach(el=>el.onclick=e=>{e.stopPropagation();detail(el.dataset.detail)});document.querySelectorAll('[data-recon]').forEach(el=>el.onclick=()=>detail(el.dataset.recon,true));for(const id of ['branch','severity','status'])if($('#'+id))$('#'+id).onchange=e=>{if(id==='branch')branch=e.target.value;if(id==='severity')severity=e.target.value;if(id==='status')status=e.target.value;render()};if($('#search'))$('#search').oninput=e=>{let pos=e.target.selectionStart;query=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)};if($('#clear'))$('#clear').onclick=()=>{query='';branch='All branches';severity='All severities';status='All statuses';render()};if($('#export'))$('#export').onclick=exportJournals;if($('#run'))$('#run').onclick=()=>{alerts=detect();render();toast('Detection complete · '+alerts.length+' journals flagged')};if($('#exportRecon'))$('#exportRecon').onclick=()=>download('SYNTHETIC-reconciliation.csv',[['Demo data','ID','Account','Branch','GL','Source','Variance','Reason','Status'],...recon.map(r=>['SYNTHETIC',r.id,r.account,r.branch,r.gl,r.source,r.gl-r.source,r.reason,r.gl===r.source?'Matched':state(r.id).status])]);}
function detail(id,isRecon=false){sourceDialog(id,isRecon)}
function observed(r,t){if(r.evidence)return t.rawScore.toFixed(3);switch(r.kind){case'amount':case'period':return money(t.amount);case'hours':return String(t.hour).padStart(2,'0')+':00';case'dormant':return t.inactiveDays+' inactive days';case'reversal':return t.reversals+' reversals';case'duplicate':return rows.filter(x=>x.reference===t.reference&&x.account===t.account&&x.branch===t.branch&&x.date===t.date&&x.amount===t.amount).length+' matching journals';case'interbranch':return money(Math.abs(t.amount-t.counterpart))+' absolute difference';}}

function modeSelector(){return `<div class="modebar"><div><span class="eyebrow">DETECTION APPROACH</span><p>Explore the same journals through three analytical lenses.</p></div><select id="mode" aria-label="Detection approach">${[['rules','Rule-based detection'],['statistical','Statistical anomaly detection'],['machine','Machine learning anomaly detection']].map(([v,n])=>`<option value="${v}" ${mode===v?'selected':''}>${n}</option>`).join('')}</select><a href="#models" class="link">Configure & compare →</a></div>`}
function studio(){let r=GL.evaluate(rows,rules),s=Analytics.statistical(rows,modelConfig).filter(t=>t.flagged),m=Analytics.machine(rows,modelConfig).filter(t=>t.flagged),sets=[new Set(r.map(t=>t.id)),new Set(s.map(t=>t.id)),new Set(m.map(t=>t.id))],union=[...new Set([...r,...s,...m].map(t=>t.id))];let scores=Analytics.machine(rows,modelConfig);return heading('Detection studio','Compare explainable controls, historical deviations and multivariate patterns.','<button id="applyModels" class="primary">Apply settings & run</button>')+`<div class="callout"><b>Three approaches. One synthetic ledger.</b> Statistical and ML methods use ${Analytics.historical.length.toLocaleString()} separate synthetic August baseline records; September journals are scored without fitting on them. This illustrates model mechanics, not validated MBSL detection performance. Signals require investigation; production logic and models require requirements, data assessment and calibration.</div><div class="approaches">${[['01','Rule-based','Predefined accounting controls',r.length,'rules'],['02','Statistical','Account-level amount deviations',s.length,'statistical'],['03','Machine learning','Isolation Forest · six input features',m.length,'machine']].map(([n,title,desc,count,v])=>`<section class="panel approach ${mode===v?'selected':''}"><span class="eyebrow">APPROACH ${n}</span><h2>${title}</h2><p>${desc}</p><strong>${count}</strong><small>flagged journals</small><button data-use="${v}">Explore ${title.toLowerCase()} →</button></section>`).join('')}</div><div class="grid"><section class="panel"><h2>Statistical detection</h2><p class="muted">Compare each journal amount to 120 August records for its GL account.</p><div class="modelsettings"><label>Technique<select id="statMethod"><option value="zscore" ${modelConfig.method==='zscore'?'selected':''}>Absolute Z-score</option><option value="iqr" ${modelConfig.method==='iqr'?'selected':''}>Interquartile range (IQR)</option></select></label><label>Z-score cutoff<input id="zCutoff" type="number" min="1" max="8" step="0.1" value="${modelConfig.z}"></label><label>IQR multiplier<input id="iqrCutoff" type="number" min="0.5" max="5" step="0.1" value="${modelConfig.iqr}"></label></div><div class="methodnote">Z-score: |amount − account mean| / population standard deviation, flagged above cutoff.<br>IQR: flagged below Q1 − multiplier × IQR or above Q3 + multiplier × IQR. Settings apply only to their selected technique. No forecasting or seasonality model is included.</div></section><section class="panel"><h2>Machine learning detection</h2><p class="muted">A compact, seeded Isolation Forest trained on the August baseline.</p><div class="modelsettings"><label>Anomaly score cutoff<input id="mlCutoff" type="number" min="0.40" max="0.85" step="0.01" value="${modelConfig.threshold}"></label><label>Isolation trees<select id="treeCount">${[32,64,128].map(n=>`<option ${modelConfig.trees===n?'selected':''}>${n}</option>`).join('')}</select></label></div><div class="methodnote">Features: log amount, posting hour, log inactivity days, reversal count, counterpart variance ratio and manual posting indicator. Random partitions isolate unusual combinations with shorter average paths. Score 0–1; higher is more unusual. Not a probability. Fixed seed: 1977 · sample size: 128 per tree.</div></section></div><section class="panel" style="margin-bottom:22px"><div class="panelhead"><div><h2>ML score distribution</h2><small>All ${rows.length} September journals · cutoff ${modelConfig.threshold.toFixed(2)} · ${m.length} flagged</small></div><span class="pill">Unsupervised · demo model</span></div><div class="chart">${Array.from({length:10},(_,i)=>{let n=scores.filter(t=>Math.min(9,Math.floor(t.rawScore*10))===i).length;return `<div class="barcol"><small>${n}</small><div class="bar ${i/10>=modelConfig.threshold?'hot':''}" style="height:${Math.max(2,n/rows.length*180)}px"></div><small>${(i/10).toFixed(1)}</small></div>`}).join('')}</div><div class="methodnote">Bins show the lower score bound; the cutoff applies to each journal’s exact score, not bin colour. Model fitting is in-browser and deterministic. No labelled fraud data, accuracy estimate or production model registry is included.</div></section><section class="panel"><div class="panelhead"><div><h2>Cross-method signal comparison</h2><small>${union.length} unique flagged journals · overlap is not independent corroboration</small></div></div><div class="tablewrap"><table><thead><tr><th>Journal / branch</th><th>Amount</th><th>Rule-based</th><th>Statistical</th><th>Machine learning</th><th></th></tr></thead><tbody>${union.map(id=>{let t=rows.find(x=>x.id===id);return `<tr><td><strong>${id}</strong><small>${t.branch}</small></td><td>${money(t.amount)}</td>${sets.map(set=>`<td>${set.has(id)?'<span class="pill High">Flagged</span>':'<span class="muted">—</span>'}</td>`).join('')}<td><button class="link" data-compare="${id}">Inspect signals ↗</button></td></tr>`}).join('')||'<tr><td colspan="6" class="empty">No methods flag journals with current settings.</td></tr>'}</tbody></table></div></section><p class="methodnote">Implementation reference: <a href="https://scikit-learn.org/stable/modules/generated/sklearn.ensemble.IsolationForest.html" target="_blank" rel="noopener">Isolation Forest algorithm documentation</a>. This is a compact JavaScript implementation, not the scikit-learn library. Contextual feature deviations in drilldowns are not SHAP or causal explanations.</p>`}
function bindModels(){if($('#mode'))$('#mode').onchange=e=>{mode=e.target.value;saveModelSettings();alerts=detect();render()};document.querySelectorAll('[data-use]').forEach(b=>b.onclick=()=>{mode=b.dataset.use;saveModelSettings();alerts=detect();location.hash='exceptions'});document.querySelectorAll('[data-compare]').forEach(b=>b.onclick=()=>{let id=b.dataset.compare,rule=GL.evaluate(rows,rules).find(t=>t.id===id),stat=Analytics.statistical(rows,modelConfig).find(t=>t.id===id),ml=Analytics.machine(rows,modelConfig).find(t=>t.id===id);$('#detailContent').innerHTML=`<div class="panelhead"><div><div class="eyebrow">CROSS-METHOD EVIDENCE</div><h1>${id}</h1><small>Synthetic journal · August baseline / September scoring</small></div><button id="closeCompare" aria-label="Close comparison">✕</button></div>${[['Rule-based',rule],['Statistical',stat],['Machine learning',ml]].map(([name,t])=>`<h3>${name} ${t?.hits.length?'<span class="pill">Flagged</span>':'<span class="pill">No signal</span>'}</h3>${t?.hits.map(h=>`<div class="evidence"><b>${esc(h.name)}</b><br>${esc(h.description)}</div>`).join('')||'<p class="muted">No signal at current settings.</p>'}`).join('')}<p class="methodnote">Open the selected method’s exception workbench to record an investigation. Case history is shared across methods for the same journal.</p>`;$('#closeCompare').onclick=()=>$('#detail').close();$('#detail').showModal()});if($('#applyModels'))$('#applyModels').onclick=()=>{for(const id of ['zCutoff','iqrCutoff','mlCutoff'])if(!$('#'+id).checkValidity()||!$('#'+id).value){$('#'+id).reportValidity();return}modelConfig={method:$('#statMethod').value,z:+$('#zCutoff').value,iqr:+$('#iqrCutoff').value,threshold:+$('#mlCutoff').value,trees:+$('#treeCount').value};saveModelSettings();alerts=detect();render();toast('Statistical settings applied and Isolation Forest fitted')};}
function saveModelSettings(){try{localStorage.setItem('vx-mode',JSON.stringify(mode));localStorage.setItem('vx-models',JSON.stringify(modelConfig))}catch{toast('Settings apply for this session only.')}}


const kindLabels={amount:'High-value journal',hours:'Outside business hours',dormant:'Dormant account activity',reversal:'Repeated reversal',period:'Period-end adjustment',duplicate:'Duplicate reference',interbranch:'Interbranch imbalance'};
function permissionNote(){return `<div class="callout governance-note"><b>Role simulation · ${esc(currentUser().name)} (${currentUser().role})</b><br>Switch demo identities in the header to explore permissions. This is browser-local UI enforcement, not authentication. Rules activate only after independent approval. Local history can be edited or cleared outside the app; it is not an immutable audit trail.</div>`}
function managedRules(){let author=Governance.can(currentUser(),'author');return heading('Detection rules',`Approved rule set v${governance.version} · ${rules.length} controls · ${rules.filter(r=>r.enabled).length} enabled`,`<a class="link" href="#governance">Approvals & history →</a><button id="addRule" class="primary" ${author?'':'disabled'}>＋ Add rule</button>`)+permissionNote()+`<div class="callout">Add, edit, duplicate, enable, disable or delete controls using seven supported detection types. Changes are saved as drafts and require approval. <b>Preview impact</b> compares rule-based flags on the synthetic September ledger, regardless of the selected dashboard detection approach.</div><div class="rulegrid">${rules.map(r=>`<section class="panel rulecard"><div class="panelhead"><div><span class="eyebrow">${esc(r.id)} · ${esc(r.kind)}</span><h3>${esc(r.name)}</h3></div>${badge(r.enabled?'Enabled':'Disabled')}</div><p>${esc(r.description)}</p><div class="rule-summary"><span>Threshold <b>${r.threshold.toLocaleString()}</b></span><span>Severity ${badge(r.severity)}</span></div><small>${esc(kindLabels[r.kind])} · approved set v${governance.version}</small><div class="rule-actions"><button data-edit-rule="${esc(r.id)}" ${author?'':'disabled'}>Edit</button><button data-copy-rule="${esc(r.id)}" ${author?'':'disabled'}>Duplicate</button><button data-toggle-rule="${esc(r.id)}" ${author?'':'disabled'}>${r.enabled?'Disable':'Enable'}</button><button data-rule-history="${esc(r.id)}">History</button><button class="danger-text" data-delete-rule="${esc(r.id)}" ${author?'':'disabled'}>Delete</button></div></section>`).join('')||'<div class="panel empty">No approved rules. An author can add a rule and submit it for approval.</div>'}</div>`}
function ruleDiff(before,after){let changes=[];for(let r of before){let n=after.find(x=>x.id===r.id);if(!n)changes.push({id:r.id,name:r.name,type:'Deleted',before:r,after:null});else if(JSON.stringify(r)!==JSON.stringify(n))changes.push({id:r.id,name:n.name,type:'Changed',before:r,after:n});}for(let r of after)if(!before.some(x=>x.id===r.id))changes.push({id:r.id,name:r.name,type:'Added',before:null,after:r});return changes}
function impact(before,after){let a=GL.evaluate(rows,before),b=GL.evaluate(rows,after),added=b.filter(t=>!a.some(x=>x.id===t.id)),removed=a.filter(t=>!b.some(x=>x.id===t.id));return `<div class="impact"><b>Rule-based impact preview</b><div class="impactnums"><span>${a.length} → ${b.length}<small>Flagged journals</small></span><span>+${added.length}<small>Newly flagged</small></span><span>−${removed.length}<small>No longer flagged</small></span></div><small>${rows.length} synthetic journals · journal membership only; signal, severity and priority may change even if counts stay the same.</small><p>New: ${added.map(t=>t.id).join(', ')||'None'}<br>Removed: ${removed.map(t=>t.id).join(', ')||'None'}</p></div>`}
function governancePage(){let pending=governance.requests.filter(r=>r.status==='Pending'),drafts=governance.requests.filter(r=>r.status==='Draft');return heading('Roles & governance','Demonstrate controlled rule changes, independent approval and traceable decisions.')+permissionNote()+`<div class="stats"><div class="stat accent"><label>Approved rule set</label><strong>v${governance.version}</strong><small>${rules.length} current controls</small></div><div class="stat"><label>Draft requests</label><strong>${drafts.length}</strong><small>Not active in detection</small></div><div class="stat warn"><label>Awaiting approval</label><strong>${pending.length}</strong><small>Independent reviewer required</small></div><div class="stat"><label>Audit events</label><strong>${governance.audit.length}</strong><small>Local demonstration history</small></div></div><div class="callout"><b>Try the workflow:</b> As Rule Author, add or edit a control, preview impact and save a draft. Submit it, then switch to Approver to review and activate it. Switch to Auditor to inspect history with editing disabled.</div><section class="panel govpanel"><h2>Role-based permission demonstration</h2><p class="muted">Choose an identity in the header. Disabled actions demonstrate the selected role’s permissions.</p><div class="tablewrap"><table><thead><tr><th>Capability</th>${Governance.users.map(u=>`<th>${u.role}</th>`).join('')}</tr></thead><tbody>${[['Read dashboards, cases and history','read'],['Explore model settings (sandbox only)','sandbox'],['Create rule drafts / submit own drafts','author'],['Approve / reject another identity’s request','review'],['Update investigations','investigate']].map(([label,action])=>`<tr><td>${label}</td>${Governance.users.map(u=>`<td>${Governance.can(u,action)?'<span class="pill Matched">Allowed</span>':'<span class="pill">View only</span>'}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="methodnote">Administrator can author and review, but cannot review their own requests. Identity switching is deliberately available for demonstration. Statistical / ML tuning is an exploration sandbox and is outside this approval workflow.</div></section><section class="panel govpanel"><div class="panelhead"><div><h2>Change requests</h2><small>Draft → Pending → Approved / Rejected · approved changes activate immediately</small></div><a href="#rules" class="link">Manage controls →</a></div><div class="tablewrap"><table><thead><tr><th>Request / action</th><th>Author</th><th>Base</th><th>Status</th><th></th></tr></thead><tbody>${[...governance.requests].reverse().map(r=>`<tr><td><strong>${r.id} · ${esc(r.action)}</strong><small>${esc(r.reason)}</small></td><td>${esc(r.creatorName)}</td><td>v${r.base}${r.base!==governance.version&&['Draft','Pending'].includes(r.status)?' · stale':''}</td><td>${badge(r.status)}</td><td><button class="link" data-request="${r.id}">Review / inspect →</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">No change requests yet. Create a draft in Detection rules to begin.</td></tr>'}</tbody></table></div></section><section class="panel govpanel"><div class="panelhead"><div><h2>Approved version history</h2><small>Full rule-set snapshots · inspect individual rule differences within each change request</small></div></div><div class="tablewrap"><table><thead><tr><th>Version</th><th>Approved by / time</th><th>Reason</th><th>Controls</th><th></th></tr></thead><tbody>${[...governance.versions].reverse().map(v=>`<tr><td><strong>v${v.version}${v.version===governance.version?' · Current':''}</strong></td><td>${esc(v.actor)}<small>${formatGovTime(v.at)}</small></td><td>${esc(v.reason)}</td><td>${v.rules.length}</td><td><button class="link" data-version="${v.version}">Inspect snapshot →</button></td></tr>`).join('')}</tbody></table></div></section><section class="panel govpanel"><div class="panelhead"><div><h2>Audit history</h2><small>Append-only through the demo UI · browser-local and not tamper-proof</small></div><button id="exportAudit">↓ Export audit CSV</button></div><div class="tablewrap"><table><thead><tr><th>Event</th><th>Actor / role</th><th>Target</th><th>Details</th></tr></thead><tbody>${[...governance.audit].reverse().map(a=>`<tr><td><strong>#${a.seq} · ${esc(a.event)}</strong><small>${formatGovTime(a.at)}</small></td><td>${esc(a.actor)}<small>${esc(a.role)}</small></td><td>${esc(a.target)}</td><td>${esc(a.details)}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">Workflow events will appear here as you use the demo.</td></tr>'}</tbody></table></div></section>`}
function formatGovTime(at){return esc(new Date(at).toLocaleString('en-GB',{timeZone:'Asia/Colombo'}))+' SLST'}
function govDialog(content){$('#detailContent').innerHTML=content;$('#detailContent').querySelectorAll('[data-close-gov]').forEach(b=>b.onclick=()=>$('#detail').close());if(!$('#detail').open)$('#detail').showModal()}
function govHeader(title,sub='Rule governance · synthetic demo'){return `<div class="panelhead"><div><div class="eyebrow">${sub}</div><h1>${esc(title)}</h1></div><button data-close-gov aria-label="Close dialog">✕</button></div>`}
function attemptGov(fn){try{fn()}catch(e){toast(e.message)}}
function newRuleId(){return 'R-'+crypto.randomUUID().slice(0,8)}
function editor(id,duplicate=false){if(!Governance.can(currentUser(),'author')){toast('Author permission required.');return}let source=rules.find(r=>r.id===id),r=source?structuredClone(source):{...structuredClone(GL.defaults[0]),id:newRuleId(),name:'',description:''};if(duplicate){r.id=newRuleId();r.name+=' (copy)'}let action=!source?'Add rule':duplicate?'Duplicate rule':'Edit rule';govDialog(govHeader(action)+`<div class="editorfields"><label>Rule name<input id="editName" maxlength="100" value="${esc(r.name)}" required></label><label>Detection type<select id="editKind">${Object.entries(kindLabels).map(([k,n])=>`<option value="${k}" ${r.kind===k?'selected':''}>${n}</option>`).join('')}</select></label><label>Description<textarea id="editDescription" maxlength="1000" required>${esc(r.description)}</textarea></label><div class="modelsettings"><label>Threshold<input type="number" id="editThreshold" value="${r.threshold}" min="0.01" max="999999999" step="any" required></label><label>Severity<select id="editSeverity"><option ${r.severity==='High'?'selected':''}>High</option><option ${r.severity==='Medium'?'selected':''}>Medium</option></select></label><label>Enabled<input id="editEnabled" type="checkbox" ${r.enabled?'checked':''}></label></div><p class="methodnote" id="typeSemantics"></p><label>Business rationale<textarea id="editReason" maxlength="1000" required placeholder="Why is this control needed or changing?"></textarea></label></div><div class="actions"><button id="previewRule">Preview impact</button><button id="saveRuleDraft" class="primary">Save draft</button></div><div id="ruleImpact"></div>`);function semantics(){let kind=$('#editKind').value,template=GL.defaults.find(x=>x.kind===kind);$('#typeSemantics').textContent=template.description+' '+(kind==='hours'?'Whole closing hour 9–24; opening hour remains 08:00.':kind==='duplicate'?'Whole count, at least 2.':['dormant','reversal'].includes(kind)?'Whole days/count, at least 1.':'Positive LKR amount; strict greater-than comparison.');}semantics();$('#editKind').onchange=()=>{let template=GL.defaults.find(x=>x.kind===$('#editKind').value);$('#editDescription').value=template.description;$('#editThreshold').value=template.threshold;semantics();$('#ruleImpact').innerHTML=''};function proposed(){for(let field of ['editName','editDescription','editThreshold','editReason'])if(!$('#'+field).checkValidity()){$('#'+field).reportValidity();throw Error('Complete the required fields.')}let rule={id:r.id,name:$('#editName').value.trim(),kind:$('#editKind').value,description:$('#editDescription').value.trim(),threshold:+$('#editThreshold').value,severity:$('#editSeverity').value,enabled:$('#editEnabled').checked};let next=rules.map(x=>x.id===rule.id?rule:x);if(!rules.some(x=>x.id===rule.id))next.push(rule);Governance.validate(next);return next}$('#previewRule').onclick=()=>attemptGov(()=>{$('#ruleImpact').innerHTML=impact(rules,proposed())});$('#saveRuleDraft').onclick=()=>attemptGov(()=>{let next=proposed(),request=Governance.draft(governance,currentUser(),{action,rules:next,reason:$('#editReason').value,ruleId:r.id});saveGovernance();render();requestDialog(request.id);toast('Draft saved. Submit it for independent approval.');});}
function simpleProposal(action,next,ruleId,extra=''){if(!Governance.can(currentUser(),'author')){toast('Author permission required.');return}govDialog(govHeader(action)+`<div class="callout">${extra||'This proposal becomes a draft. Approved controls remain active until an independent reviewer approves it.'}</div>${impact(rules,next)}<label class="fieldlabel">Business rationale<textarea id="proposalReason" maxlength="1000" placeholder="Explain the business reason…"></textarea></label><button class="primary" id="confirmProposal">${action==='Delete rule'?'Confirm deletion draft':'Save proposal draft'}</button>`);$('#confirmProposal').onclick=()=>attemptGov(()=>{let req=Governance.draft(governance,currentUser(),{action,rules:next,ruleId,reason:$('#proposalReason').value});saveGovernance();render();requestDialog(req.id);toast('Draft created. Approved rules have not changed.');});}
function requestDialog(id){let r=governance.requests.find(x=>x.id===id),before=governance.versions.find(v=>v.version===r.base).rules,diff=ruleDiff(before,r.rules),own=r.creator===currentUser().id,author=Governance.can(currentUser(),'author'),reviewer=Governance.can(currentUser(),'review'),stale=r.base!==governance.version;govDialog(govHeader(r.id+' · '+r.action)+`<p>${badge(r.status)} · ${esc(r.creatorName)} · Based on v${r.base}</p><div class="callout"><b>Business rationale:</b> ${esc(r.reason)}${stale&&['Draft','Pending'].includes(r.status)?'<br><b>Stale proposal:</b> approved rules have changed. Create a fresh draft; this snapshot cannot be activated.':''}</div><h3>Rule changes</h3>${diff.map(d=>`<div class="evidence"><b>${d.type} · ${esc(d.id)} · ${esc(d.name)}</b>${['name','kind','description','threshold','severity','enabled'].filter(k=>JSON.stringify(d.before?.[k])!==JSON.stringify(d.after?.[k])).map(k=>`<div><small>${k}</small> ${esc(d.before?.[k]??'—')} → ${esc(d.after?.[k]??'—')}</div>`).join('')}</div>`).join('')}${impact(before,r.rules)}<small>Impact is against the submitted base version v${r.base}, not a later version.</small>${r.status==='Draft'?`<div class="actions govactions"><button id="submitRequest" class="primary" ${own&&author&&!stale?'':'disabled'}>Submit for approval</button><button id="discardRequest" ${own&&author?'':'disabled'}>Discard draft</button></div><p class="methodnote">Only this draft’s author can submit or discard it.</p>`:''}${r.status==='Pending'?`<label class="fieldlabel">Review rationale<textarea id="reviewReason" maxlength="1000" placeholder="Record the approval or rejection reason…" ${reviewer&&!own?'':'disabled'}></textarea></label><div class="actions"><button id="approveRequest" class="primary" ${reviewer&&!own&&!stale?'':'disabled'}>Approve & activate</button><button id="rejectRequest" ${reviewer&&!own?'':'disabled'}>Reject request</button></div><p class="methodnote">Author and reviewer must be different demo identities. Switch identities in the header after closing this dialog.</p>`:''}${r.reviewer?`<div class="callout"><b>${r.status} by ${esc(r.reviewer)}</b><br>${esc(r.reviewReason)}<br>${formatGovTime(r.reviewedAt)}</div>`:''}`);if($('#submitRequest'))$('#submitRequest').onclick=()=>attemptGov(()=>{Governance.submit(governance,currentUser(),id);saveGovernance();render();requestDialog(id);toast('Submitted. Switch to Demo Approver to review.');});if($('#discardRequest'))$('#discardRequest').onclick=()=>attemptGov(()=>{Governance.discard(governance,currentUser(),id);saveGovernance();render();requestDialog(id);});for(let [button,approve] of [['approveRequest',true],['rejectRequest',false]])if($('#'+button))$('#'+button).onclick=()=>attemptGov(()=>{Governance.decide(governance,currentUser(),id,approve,$('#reviewReason').value);saveGovernance();render();requestDialog(id);toast(approve?'Approved rule set v'+governance.version+' is now active.':'Request rejected. Approved rules unchanged.');});}
function versionDialog(n){let v=governance.versions.find(x=>x.version===n);govDialog(govHeader('Approved rule set v'+n)+`<p>${esc(v.reason)} · ${esc(v.actor)}</p><small>${formatGovTime(v.at)}</small><div class="tablewrap"><table><thead><tr><th>Rule / type</th><th>Threshold</th><th>Severity</th><th>Enabled</th></tr></thead><tbody>${v.rules.map(r=>`<tr><td><strong>${esc(r.id)} · ${esc(r.name)}</strong><small>${esc(r.kind)}</small></td><td>${r.threshold}</td><td>${r.severity}</td><td>${r.enabled?'Yes':'No'}</td></tr>`).join('')}</tbody></table></div>${n!==governance.version?`<p class="methodnote">Restore this snapshot through a new change request. Later history will be retained.</p><button id="restoreVersion" ${Governance.can(currentUser(),'author')?'':'disabled'}>Propose restore to v${n}</button>`:''}`);if($('#restoreVersion'))$('#restoreVersion').onclick=()=>simpleProposal('Restore version '+n,structuredClone(v.rules),'','This creates a new approval request using the selected snapshot. Approval will create a new version; history is retained.');}
function ruleHistory(id){let last=null,entries=[];for(let v of governance.versions){let r=v.rules.find(x=>x.id===id)||null;if(JSON.stringify(r)!==JSON.stringify(last)){entries.push({v,r});last=r}}govDialog(govHeader('Rule history · '+id)+entries.reverse().map(({v,r})=>`<div class="evidence"><b>Approved set v${v.version} · ${r?esc(r.name):'Deleted'}</b><br>${formatGovTime(v.at)} · ${esc(v.actor)}<br>${r?esc(kindLabels[r.kind])+' · Threshold '+r.threshold+' · '+r.severity+' · '+(r.enabled?'Enabled':'Disabled'):'Definition retained in earlier snapshots.'}<br>${esc(v.reason)}</div>`).join('')+'<p class="methodnote">Only approved revisions appear here. Pending changes are listed under change requests.</p>')}
function bindGovernance(){document.querySelectorAll('[data-rule-history]').forEach(b=>b.onclick=()=>ruleHistory(b.dataset.ruleHistory));let selector=$('#demoIdentity');selector.innerHTML=Governance.users.map(u=>`<option value="${u.id}" ${identity===u.id?'selected':''}>${u.name} · ${u.role}</option>`).join('');selector.onchange=e=>{let previous=currentUser().name;identity=e.target.value;Governance.audit(governance,currentUser(),'Demo identity switched','Session',previous+' → '+currentUser().name);saveGovernance();render();toast('Simulating '+currentUser().role+' permissions');};if($('#addRule'))$('#addRule').onclick=()=>editor();document.querySelectorAll('[data-edit-rule]').forEach(b=>b.onclick=()=>editor(b.dataset.editRule));document.querySelectorAll('[data-copy-rule]').forEach(b=>b.onclick=()=>editor(b.dataset.copyRule,true));document.querySelectorAll('[data-toggle-rule]').forEach(b=>b.onclick=()=>{let r=rules.find(x=>x.id===b.dataset.toggleRule);simpleProposal(r.enabled?'Disable rule':'Enable rule',rules.map(x=>x.id===r.id?{...x,enabled:!x.enabled}:x),r.id)});document.querySelectorAll('[data-delete-rule]').forEach(b=>b.onclick=()=>{let r=rules.find(x=>x.id===b.dataset.deleteRule);simpleProposal('Delete rule',rules.filter(x=>x.id!==r.id),r.id,`Confirm a deletion draft for <b>${esc(r.name)}</b>. The approved rule is retained until approval, and previous versions keep its definition.`)});document.querySelectorAll('[data-request]').forEach(b=>b.onclick=()=>requestDialog(b.dataset.request));document.querySelectorAll('[data-version]').forEach(b=>b.onclick=()=>versionDialog(+b.dataset.version));if($('#exportAudit'))$('#exportAudit').onclick=()=>download('DEMO-governance-audit.csv',[['Sequence','UTC timestamp','Actor','Role','Event','Target','Details'],...governance.audit.map(a=>[a.seq,a.at,a.actor,a.role,a.event,a.target,a.details])]);}


const investigators=['Demo Analyst A','Demo Analyst B','Demo Finance Manager','Demo Internal Auditor'];
let caseFilters={query:'',status:'All statuses',source:'All sources',owner:'All investigators'};
function todaySL(){return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Colombo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())}
function suggestedDue(severity){let d=new Date(todaySL()+'T00:00:00Z');d.setUTCDate(d.getUTCDate()+(severity==='High'?5:10));return d.toISOString().slice(0,10)}
function migrateInvestigations(legacy){let store=Investigations.initial();for(let [id,old] of Object.entries(legacy)){if(!old.notes?.length&&old.status==='Open')continue;let at=new Date().toISOString();store.cases.push({id:'INV-'+String(store.next++).padStart(4,'0'),sourceId:'LEGACY-'+id,source:'Legacy v1.2',title:'Archived investigation · '+id,account:'Prior synthetic dataset',branch:'Legacy',category:'Legacy archive',amount:0,severity:'Medium',status:old.status==='Resolved'?'Resolved':'Under Investigation',owner:old.owner==='Unassigned'?'':old.owner||'',dueDate:'',createdAt:at,updatedAt:at,resolution:old.status==='Resolved'?'Migrated resolution; see original notes.':'',notes:(old.notes||[]).map(n=>({at,actor:n.owner||'Legacy demo user',text:'Original record '+(n.at||'')+' · '+n.text})),timeline:[{at,actor:'Demo migration',action:'Legacy notes preserved',detail:'Archived from '+id+'. Not linked to a different journal in the expanded synthetic dataset.'}],evidence:['Original v1.2 record '+id+'; old ledger snapshot not retained. No amount inferred.']});}return store}
function saveInvestigations(eventName,target,details){try{localStorage.setItem('vx-investigations-v2',JSON.stringify(investigations))}catch{toast('Investigation changes last for this session only.')}if(eventName){Governance.audit(governance,currentUser(),eventName,target,details||'');saveGovernance();}}
function ledgerCoverage(){return `<div class="coverage"><span><b>${rows.length}</b> balanced journals</span><span><b>${GL.templates.length}</b> transaction types</span><span><b>${new Set(rows.map(t=>t.category)).size}</b> categories</span><span><b>${new Set(rows.flatMap(t=>t.lines.map(l=>l.account))).size}</b> GL accounts</span><span><b>${GL.branches.length}</b> branches</span></div><div class="callout">Synthetic accounting illustrations: each journal balances, and journal value is counted once (total debits), not twice across debit and credit lines. The account shown in the register is the primary detection account. Reconciliation snapshots remain separate examples; this release does not introduce transaction-level matching.</div>`}
function sourceData(id,isRecon=false){if(isRecon){let t=recon.find(x=>x.id===id);if(!t)return null;return {id:t.id,source:'Reconciliation',title:t.reason+' · '+t.account,account:t.account,branch:t.branch,category:'Reconciliation',amount:Math.abs(t.gl-t.source),severity:Math.abs(t.gl-t.source)>=100000?'High':'Medium',evidence:[t.reason,'GL balance '+money(t.gl),'Source balance '+money(t.source),'Signed variance (GL − source) '+money(t.gl-t.source),'Standalone synthetic balance snapshot; not derived from the journal register.'],recon:t,flagged:t.gl!==t.source};}let row=rows.find(x=>x.id===id);if(!row)return null;let t=alerts.find(x=>x.id===id)||row;return {id:t.id,source:'GL anomaly',title:t.description,account:t.account,branch:t.branch,category:t.category,amount:t.amount,severity:t.severity||'Medium',evidence:[modeName()+' detection snapshot',...(t.hits||[]).map(h=>h.name+': '+h.description),t.sourceSystem+' · '+t.sourceReference,'Operator '+t.operator+' · '+t.approvalStatus],journal:t,flagged:!!t.hits?.length};}
function journalLines(t){let totals=GL.journalTotals(t);return `<section class="journal-evidence"><div class="panelhead"><div><h3>Complete journal · ${esc(t.reference)}</h3><small>${t.lines.length} linked lines · LKR</small></div>${badge(totals.balanced?'Balanced':'Unbalanced')}</div><div class="tablewrap"><table><thead><tr><th>Line / GL account</th><th class="right">Debit</th><th class="right">Credit</th></tr></thead><tbody>${t.lines.map(l=>`<tr><td>${l.line} · ${esc(l.account)}<small>${esc(l.narration)}</small></td><td class="right">${l.debit?money(l.debit):'—'}</td><td class="right">${l.credit?money(l.credit):'—'}</td></tr>`).join('')}<tr><td><b>Journal totals</b></td><td class="right"><b>${money(totals.debit)}</b></td><td class="right"><b>${money(totals.credit)}</b></td></tr></tbody></table></div></section>`}
function feedbackView(id){let f=investigations.feedback[id];return f?`<div class="callout"><b>Reviewer feedback: ${esc(f.status)}</b><br>${esc(f.reason)}<br><small>${esc(f.actor)} · ${formatGovTime(f.at)}</small><details><summary>Review decision history (${f.history.length})</summary>${[...f.history].reverse().map(e=>`<div class="audit"><b>${esc(e.status)}</b> · ${esc(e.actor)}<small>${formatGovTime(e.at)}</small><p>${esc(e.reason)}</p></div>`).join('')}</details></div>`:''}
function sourceDialog(id,isRecon=false){let data=sourceData(id,isRecon);if(!data)return;let c=Investigations.find(investigations,id),t=data.journal,r=data.recon,allowed=Governance.can(currentUser(),'investigate');let content=govHeader(id,isRecon?'RECONCILIATION · SYNTHETIC DATA':'BALANCED JOURNAL · SYNTHETIC DATA')+`<p>${esc(data.title)}</p><div class="detailgrid">${(t?[['Journal value (total debits)',money(t.amount)],['Transaction type',t.type],['Category',t.category],['Primary detection account',t.account],['Posting',t.date+' '+String(t.hour).padStart(2,'0')+':00 SLST'],['Branch',t.branch],['Source system',t.sourceSystem],['Source reference',t.sourceReference],['Counterparty',t.counterparty],['Posting user',t.operator],['Posting approval',t.approvalStatus],['Checker',t.checker]]:[['GL balance',money(r.gl)],['Source balance',money(r.source)],['Variance (GL − source)',money(r.gl-r.source)],['Snapshot age',r.age+' days as at September close']]).map(([k,v])=>`<div><label>${esc(k)}</label><strong>${esc(v)}</strong></div>`).join('')}</div>${t?journalLines(t):''}<h3>${t?'Detection evidence · '+modeName():'Reconciliation evidence'}</h3>${t?(t.hits||[]).map(h=>`<div class="evidence"><b>${esc(h.id)} · ${esc(h.name)}</b><br>${esc(h.description)}<br>Threshold: ${h.threshold.toLocaleString()} · Observed: ${esc(observed(h,t))}</div>`).join('')||'<div class="callout">No signal from the selected method. Switch detection approach to inspect another method. No fraud conclusion is implied.</div>':`<div class="evidence">${esc(data.evidence.join(' · '))}</div>`}${feedbackView(id)}<h3>Investigation</h3>${c?`<div class="case-summary"><b>${c.id}</b> ${badge(c.status)}<p>${esc(c.owner||'Unassigned')} · Target ${c.dueDate||'not set'}${Investigations.overdue(c,todaySL())?' · OVERDUE':''}</p><button id="openSourceCase" class="primary">Open investigation →</button></div>`:`<p class="muted">No linked case. Create a case to assign an investigator, set a due date and record findings.</p><button id="createSourceCase" class="primary" ${allowed&&(data.flagged||t)?'':'disabled'}>${t&&!data.flagged?'Create journal review case':'Create investigation'}</button>`}${t?`<h3>Review feedback</h3><p class="methodnote">Review decisions are shared across detection methods for this journal. They do not remove detection signals, retrain the model or reverse postings. False-positive feedback closes an existing linked case and retains the rationale.</p><div class="actions"><button id="markReviewed" ${allowed?'':'disabled'}>Mark as reviewed</button><button id="markFalsePositive" ${allowed&&(data.flagged||investigations.feedback[id]||c?.source==='GL anomaly')?'':'disabled'}>Mark as false positive</button></div>`:''}`;govDialog(content);if($('#createSourceCase'))$('#createSourceCase').onclick=()=>attemptGov(()=>{let c=Investigations.create(investigations,currentUser(),{...data,source:t&&!data.flagged?'GL journal review':data.source});saveInvestigations('Investigation created',c.id,data.id);render();caseDialog(c.id)});if($('#openSourceCase'))$('#openSourceCase').onclick=()=>caseDialog(c.id);if($('#markReviewed'))$('#markReviewed').onclick=()=>reviewDialog(id,'Reviewed');if($('#markFalsePositive'))$('#markFalsePositive').onclick=()=>reviewDialog(id,'False Positive');}
function reviewDialog(id,decision){govDialog(govHeader(decision+' · '+id)+`<div class="callout">${decision==='False Positive'?'This records a reviewer decision and closes any linked investigation with the supplied rationale. The original journal and detection signals remain available.':'Record that the journal has been reviewed. An existing case keeps its current workflow status.'}</div><label class="fieldlabel">Decision rationale<textarea id="feedbackReason" maxlength="2000" placeholder="Record the evidence and reason for this decision…"></textarea></label><button id="confirmFeedback" class="primary">Confirm ${decision.toLowerCase()}</button>`);$('#confirmFeedback').onclick=()=>attemptGov(()=>{Investigations.review(investigations,currentUser(),id,decision,$('#feedbackReason').value);saveInvestigations('Anomaly feedback',id,decision+' · '+$('#feedbackReason').value);render();sourceDialog(id);toast('Reviewer decision recorded; detection signals retained.');});}
function filteredCases(){return investigations.cases.filter(c=>(caseFilters.status==='All statuses'||c.status===caseFilters.status)&&(caseFilters.source==='All sources'||c.source===caseFilters.source)&&(caseFilters.owner==='All investigators'||(c.owner||'Unassigned')===caseFilters.owner)&&(!caseFilters.query||[c.id,c.sourceId,c.title,c.account,c.branch,c.owner,c.category].join(' ').toLowerCase().includes(caseFilters.query.toLowerCase()))).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt))}
function investigationPage(){let list=filteredCases(),open=investigations.cases.filter(c=>!['Resolved','Closed'].includes(c.status)),overdue=open.filter(c=>Investigations.overdue(c,todaySL()));return heading('Investigation register','One case journey for journal anomalies, reconciliation exceptions and archived notes.','<button id="exportCases">↓ Export register</button>')+`<div class="stats"><div class="stat accent"><label>Total cases</label><strong>${investigations.cases.length}</strong><small>Shared across detection approaches</small></div><div class="stat"><label>Open investigations</label><strong>${open.length}</strong><small>Excludes Resolved and Closed</small></div><div class="stat warn"><label>Past target date</label><strong>${overdue.length}</strong><small>Based on today in Sri Lanka</small></div><div class="stat"><label>Pending clarification</label><strong>${open.filter(c=>c.status==='Pending Clarification').length}</strong><small>Awaiting supporting information</small></div></div><div class="callout"><b>Start from a finding.</b> Open a journal or reconciliation exception and create an investigation. Assign an investigator and due date, document findings, then resolve and close. Reopen a resolved or closed case when new evidence emerges. This is a browser-local workflow simulation; cases are not shared across users’ browsers.</div><div class="filters"><input type="search" id="caseSearch" aria-label="Search investigations" placeholder="Search case, finding, account or owner…" value="${esc(caseFilters.query)}"><select id="caseStatusFilter" aria-label="Filter case status">${['All statuses',...Investigations.statuses].map(x=>`<option ${x===caseFilters.status?'selected':''}>${x}</option>`).join('')}</select><select id="caseSourceFilter" aria-label="Filter case source">${['All sources','GL anomaly','GL journal review','Reconciliation','Legacy v1.2'].map(x=>`<option ${x===caseFilters.source?'selected':''}>${x}</option>`).join('')}</select><select id="caseOwnerFilter" aria-label="Filter investigator">${['All investigators','Unassigned',...investigators].map(x=>`<option ${x===caseFilters.owner?'selected':''}>${x}</option>`).join('')}</select><button id="clearCaseFilters">Clear filters</button></div><section class="panel"><div class="panelhead"><h2>Cases & follow-up</h2><small>${list.length} matching cases</small></div><div class="tablewrap"><table><thead><tr><th>Case / source</th><th>Finding / category</th><th>Owner / target date</th><th>Severity</th><th>Status</th><th></th></tr></thead><tbody>${list.map(c=>`<tr><td><strong>${c.id}</strong><small>${esc(c.source)} · ${esc(c.sourceId)}</small></td><td><strong>${esc(c.title)}</strong><small>${esc(c.category)} · ${esc(c.branch)}</small></td><td>${esc(c.owner||'Unassigned')}<small class="${Investigations.overdue(c,todaySL())?'overdue':''}">${c.dueDate||'Target not set'}${Investigations.overdue(c,todaySL())?' · Overdue':''}</small></td><td>${badge(c.severity)}</td><td>${badge(c.status)}</td><td><button class="link" data-case="${c.id}">Open case ↗</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">No matching investigations. Create a case from a journal or reconciliation exception.</td></tr>'}</tbody></table></div></section>`}
function caseDialog(id){let c=investigations.cases.find(x=>x.id===id);if(!c)return;let allowed=Governance.can(currentUser(),'investigate'),data=sourceData(c.sourceId,c.source==='Reconciliation'),feedback=investigations.feedback[c.sourceId],choices=Investigations.transitions[c.status];govDialog(govHeader(c.id,'INVESTIGATION · BROWSER-LOCAL DEMO')+`<p>${esc(c.title)} ${badge(c.status)}</p><div class="detailgrid">${[['Finding',c.sourceId],['Origin',c.source],['Primary account',c.account],['Branch',c.branch],['Amount / variance',c.source==='Legacy v1.2'?'Not retained in legacy snapshot':money(c.amount)],['Severity',c.severity]].map(([k,v])=>`<div><label>${k}</label><strong>${esc(v)}</strong></div>`).join('')}</div>${data?'<button id="openCaseFinding">Open original finding ↗</button>':'<div class="callout">Legacy archive: notes retained from the prior dataset. The original ledger snapshot is unavailable; this case is not linked to a replacement journal.</div>'}${feedbackView(c.sourceId)}<h3>Assignment & target</h3><div class="modelsettings"><label>Investigator<select id="assignOwner" ${allowed&&c.status!=='Closed'?'':'disabled'}><option value="">Select investigator</option>${[...new Set([...investigators,...(c.owner?[c.owner]:[])])].map(x=>`<option ${x===c.owner?'selected':''}>${esc(x)}</option>`).join('')}</select></label><label>Target date<input type="date" id="assignDue" value="${c.dueDate||suggestedDue(c.severity)}" ${allowed&&c.status!=='Closed'?'':'disabled'}></label></div><button id="saveAssignment" ${allowed&&c.status!=='Closed'?'':'disabled'}>Save assignment</button>${Investigations.overdue(c,todaySL())?'<p class="overdue">This case is past its target date.</p>':''}<h3>Workflow status</h3><div class="modelsettings"><label>Next status<select id="nextCaseStatus" ${allowed?'':'disabled'}>${choices.map(s=>`<option>${s}</option>`).join('')}</select></label></div><label class="fieldlabel">Resolution / transition rationale<textarea id="caseResolution" maxlength="2000" ${allowed?'':'disabled'} placeholder="Required to resolve or close; optional for other transitions…">${esc(c.resolution)}</textarea></label><button id="transitionCase" class="primary" ${allowed?'':'disabled'}>Update status</button><h3>Supporting evidence captured at case creation</h3>${c.evidence.map(e=>`<div class="evidence">${esc(e)}</div>`).join('')||'<p class="muted">No evidence captured.</p>'}<p class="methodnote">Evidence is a snapshot. The original finding uses current detection settings. No file uploads or external evidence store are included.</p><h3>Investigation notes</h3>${c.notes.map(n=>`<div class="audit"><small>${esc(n.actor)} · ${formatGovTime(n.at)}</small><br>${esc(n.text)}</div>`).join('')||'<p class="muted">No notes recorded yet.</p>'}<textarea id="newCaseNote" aria-label="New investigation note" maxlength="2000" placeholder="Document findings and follow-up (synthetic information only)…" ${allowed?'':'disabled'}></textarea><button id="addCaseNote" ${allowed?'':'disabled'}>Add note</button><h3>Case timeline</h3>${[...c.timeline].reverse().map(e=>`<div class="timeline-entry"><b>${esc(e.action)}</b><small>${esc(e.actor)} · ${formatGovTime(e.at)}</small><p>${esc(e.detail)}</p></div>`).join('')}<p class="methodnote">Resolution closes the workflow only. It does not change GL amounts, reconcile the underlying balances or remove computed detection signals.</p>`);if($('#openCaseFinding'))$('#openCaseFinding').onclick=()=>sourceDialog(c.sourceId,c.source==='Reconciliation');$('#saveAssignment').onclick=()=>attemptGov(()=>{Investigations.assign(investigations,currentUser(),id,$('#assignOwner').value,$('#assignDue').value);saveInvestigations('Investigation assigned',id,$('#assignOwner').value+' · '+$('#assignDue').value);render();caseDialog(id);toast('Assignment and target saved.');});$('#transitionCase').onclick=()=>attemptGov(()=>{let next=$('#nextCaseStatus').value;Investigations.change(investigations,currentUser(),id,next,$('#caseResolution').value);saveInvestigations('Investigation status changed',id,next);render();caseDialog(id);toast('Case status updated.');});$('#addCaseNote').onclick=()=>attemptGov(()=>{Investigations.note(investigations,currentUser(),id,$('#newCaseNote').value);saveInvestigations('Investigation note added',id,$('#newCaseNote').value);render();caseDialog(id);});}
function bindInvestigations(){document.querySelectorAll('[data-case]').forEach(b=>b.onclick=()=>caseDialog(b.dataset.case));if($('#caseSearch'))$('#caseSearch').oninput=e=>{let p=e.target.selectionStart;caseFilters.query=e.target.value;render();$('#caseSearch').focus();$('#caseSearch').setSelectionRange(p,p)};for(let [id,key] of [['caseStatusFilter','status'],['caseSourceFilter','source'],['caseOwnerFilter','owner']])if($('#'+id))$('#'+id).onchange=e=>{caseFilters[key]=e.target.value;render()};if($('#clearCaseFilters'))$('#clearCaseFilters').onclick=()=>{caseFilters={query:'',status:'All statuses',source:'All sources',owner:'All investigators'};render()};if($('#exportCases'))$('#exportCases').onclick=()=>download('SYNTHETIC-investigation-register.csv',[['Case','Finding','Origin','Category','Account','Branch','LKR amount','Severity','Owner','Target date','Status','Overdue','Resolution'],...filteredCases().map(c=>[c.id,c.sourceId,c.source,c.category,c.account,c.branch,c.source==='Legacy v1.2'?'':c.amount,c.severity,c.owner,c.dueDate,c.status,Investigations.overdue(c,todaySL())?'Yes':'No',c.resolution])]);}

window.addEventListener('hashchange',()=>{query='';branch='All branches';severity='All severities';status='All statuses';render();window.scrollTo(0,0)});render();
